         */connectionName: String, connectionVerified: Bool, hostType: String, resourceId: String, resourceAlias: String, service: String, environment: String, summary: String, requested: AccessSpecFfi, excludedFields: [ExcludedFieldsFfi], executorId: String, executorName: String, protectionLevel: String, recipients: [RecipientFfi], status: String, createdAt: Int64, expiresAt: Int64, operationId: String?, 
        /**
         * Broker / executor that sent the request (decision goes back to it).
         */senderExecutorId: String, 
        /**
         * Whether a vault entry is bound to this resource (needed to deliver a credential).
         */credentialBound: Bool, 
        /**
